//! The app icon file (assets/rust-dirstat.ico, generated by examples/make_icon.rs) is a valid
//! .ico with every size Windows asks for, each stored as a PNG.

#[test]
fn ico_has_all_sizes_as_png() {
    let ico = std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/rust-dirstat.ico")).unwrap();
    let u16_at = |i: usize| u16::from_le_bytes([ico[i], ico[i + 1]]);
    let u32_at = |i: usize| u32::from_le_bytes([ico[i], ico[i + 1], ico[i + 2], ico[i + 3]]) as usize;
    assert_eq!((u16_at(0), u16_at(2)), (0, 1), "icon file header");
    let count = usize::from(u16_at(4));
    let mut sizes = Vec::new();
    for entry in 0..count {
        let at = 6 + 16 * entry;
        let size = if ico[at] == 0 { 256 } else { u32::from(ico[at]) };
        assert_eq!(ico[at], ico[at + 1], "square image");
        let (len, offset) = (u32_at(at + 8), u32_at(at + 12));
        assert!(offset + len <= ico.len(), "image {size} lies inside the file");
        assert_eq!(&ico[offset..offset + 8], b"\x89PNG\r\n\x1a\n", "image {size} is a PNG");
        sizes.push(size);
    }
    assert_eq!(sizes, [16, 20, 24, 32, 40, 48, 64, 128, 256]);
}
